import json, math, re
mine=[]
for l in open('map.log'):
    try:
        p=json.loads(l); mine.append((p['t'],p['x'],p['y'],float(p['d11'])))
    except: pass
theirs=[]
for l in open('rx.log'):
    m=re.match(r'([\d.]+) botB PING x=([-\d.]+) y=([-\d.]+)',l)
    if m: theirs.append((float(m.group(1)),float(m.group(2)),float(m.group(3))))
# match by time (except the buffered burst at 1788321480: exclude t in [321470,321490])
pairs=[]
import bisect
ts=[m[0] for m in mine]
for t,bx,by in theirs:
    if 1788321400<t<1788321500: continue
    i=bisect.bisect(ts,t)
    for j in (i-1,i):
        if 0<=j<len(mine) and abs(mine[j][0]-t)<2:
            pairs.append((mine[j][1],mine[j][2],bx,by,mine[j][3])); break
print(len(pairs),"pairs")
best=None
for dxi in range(-40,41):
  for dyi in range(-40,41):
    dx,dy=dxi*0.25,dyi*0.25
    ds=[math.hypot(ax-(bx+dx),ay-(by+dy)) for ax,ay,bx,by,_ in pairs]
